import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_defining_handl","description":"","frontmatter":{},"headers":[],"relativePath":"api/kernel/handl_defining_handl/index.md","filePath":"api/kernel/handl_defining_handl/index.md"}`),a={name:`api/kernel/handl_defining_handl/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-defining-handl" tabindex="-1">handl_defining_handl <a class="header-anchor" href="#handl-defining-handl" aria-label="Permalink to “handl_defining_handl”">​</a></h1><h1 id="handl-defining-handl-1" tabindex="-1">handl-defining-handl <a class="header-anchor" href="#handl-defining-handl-1" aria-label="Permalink to “handl-defining-handl”">​</a></h1><p>The <strong>self-hosting infrastructure</strong> for ADR-0044 Phase 8.</p><p>ADR-0044 Phase 8 specifies: &quot;<code>Language</code> carries an <code>eval</code> capability; a <code>Language</code> value describes handl itself. Ship a <code>handl-defining-handl</code> data file loaded as a <code>Language</code> value, evaluated under itself. The bootstrap becomes <code>compile(handlLanguage, native)</code> via the cranelift engine.&quot;</p><p>This crate produces a [<code>Language</code>] value that describes the <strong>subset</strong> of handl the data-driven engines can evaluate — the constructs migrated to the data-driven model in Phases 4–5 (value, var, the binary arithmetic / comparison ops, unary not, block bindings (<code>do { x = v; ... }</code>), if, ternary, function, call, pipe, paren, apply). It is the &quot;handl defining handl&quot;: the language spec as data.</p><h2 id="scope-honest-deliverable" tabindex="-1">Scope (honest deliverable) <a class="header-anchor" href="#scope-honest-deliverable" aria-label="Permalink to “Scope (honest deliverable)”">​</a></h2><p>Phases 4–5 migrated a <strong>representative subset</strong> of handl&#39;s ~50 constructs to the data-driven model. <strong>Full self-hosting of the entire handl language is not achievable yet</strong> — constructs whose eval schemes dispatch to <code>Foreign</code> host functions (match, handle, flow, fanout, field-access, import, export, module, template, resolve, json, hello.greet) are not compilable by the bytecode/cranelift engines, and several <code>Prim</code> ops (array, object, index, assign) are not yet implemented in any engine. The <code>type-annot</code> construct uses a <code>Bind</code> with <code>$payload</code> (reads <code>payload[&quot;name&quot;]</code>) but a type annotation has no natural bind name, so it is blocked until the payload convention is clarified. This crate does <strong>not</strong> attempt to describe the full handl language as data. Instead it:</p><ol><li>Builds the <strong>self-hosting infrastructure</strong>: a [<code>Language</code>] value describing the subset, assembled from the canonical YAML data files via [<code>language</code>].</li><li>Provides a <strong>self-hosting corpus</strong> ([<code>corpus</code>]) of subset programs used by the integration tests (<code>self_host.rs</code>, <code>bootstrap.rs</code>, <code>futamura.rs</code>) to prove the self-hosting <em>mechanism</em>. ADR-0052 Phase D adds an <strong>arrow-authored corpus</strong> ([<code>proc_corpus</code>]) demonstrating the arrow-calculus authoring surface (<code>x ~&gt; body</code>).</li></ol><p>What is <strong>proven</strong>: a <code>Language</code> value can describe a language and be evaluated under itself (across all three eval engines: tree-walk, bytecode, cranelift), and compiled to native code via the cranelift engine — the Futamura projection sanity check.</p><p>What is <strong>deferred</strong>: full handl self-hosting (pending migration of the remaining constructs — primarily <code>Foreign</code>-dispatched constructs and the unimplemented <code>Prim</code> ops), and a standalone-binary bootstrap (writing an executable to disk). Phase 8 proves the <em>mechanism</em>, not the standalone-binary artifact.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-defining-handl-2" tabindex="-1"><a href="./handl_defining_handl.html"><code>handl_defining_handl</code></a> <a class="header-anchor" href="#handl-defining-handl-2" aria-label="Permalink to “handl_defining_handl”">​</a></h3><p><em>1 struct, 3 functions</em></p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};